#!/usr/bin/env python3
"""Compare or inspect R1BT v1 semantic behaviour traces generated by RAC1_BEHAV_TRACE.

Usage:
  verify_trace.py <baseline.r1bt> <candidate.r1bt> [--float-eps 0.0] [--max-diffs 10]
  verify_trace.py --dir <baseline_dir> <candidate_dir> [--float-eps 0.0]
  verify_trace.py --summary <trace.r1bt> [--dump-frame N]
"""

from __future__ import annotations

import argparse
import math
import os
import struct
import sys
from dataclasses import dataclass
from typing import BinaryIO, Iterator, List, Optional, Tuple

FILE_HDR_FMT = "<4sIII"
FILE_HDR_SIZE = 16

# 144-byte frame header (38 unpacked values, indices 0..37):
#   0:     Q   game_frame
#   1..10: 3i I 6i  level_id, ovl_unit, game_mode, rng_seed, bolts,
#                   hero_state, hero_substate, hero_health, hero_item, hero_ammo
#  11..20: 10f hero_pos[3], hero_rot[3], hero_vel[3], hero_anim_pos
#  21..24: 4B  hero_mode, hero_anim_cur, hero_anim_next, hero_anim_frame
#  25:     i   cam_type
#  26..32: 7f  cam_pos[3], cam_rot[3], cam_fov
#  33..37: 2i 3I ui_menu_state, ui_menu_page, moby_count, audio_count, pad_reserved
FRAME_HDR_FMT = "<QiiiIiiiiii10f4Bi7fiiIII"
FRAME_HDR_SIZE = struct.calcsize(FRAME_HDR_FMT)
assert FRAME_HDR_SIZE == 144, f"unexpected FRAME_HDR_SIZE={FRAME_HDR_SIZE}"

# 48-byte moby record (19 unpacked values, indices 0..18; index 10 is pad):
MOBY_FMT = "<hhHHbbBBBBH8f"
MOBY_SIZE = struct.calcsize(MOBY_FMT)
assert MOBY_SIZE == 48, f"unexpected MOBY_SIZE={MOBY_SIZE}"

# 16-byte audio event record (7 unpacked values, indices 0..6):
AUDIO_FMT = "<HHIhhhh"
AUDIO_SIZE = struct.calcsize(AUDIO_FMT)
assert AUDIO_SIZE == 16, f"unexpected AUDIO_SIZE={AUDIO_SIZE}"


@dataclass
class MobyRecord:
    class_id: int
    uid: int
    slot_idx: int
    mode_bits: int
    state: int
    group_id: int
    anim_cur: int
    anim_next: int
    anim_frame: int
    drawn: int
    pos: Tuple[float, float, float]
    rot: Tuple[float, float, float]
    scale: float
    anim_pos: float


@dataclass
class AudioRecord:
    kind: int
    flags: int
    id: int
    vol: int
    pan: int
    pm: int
    pb: int


@dataclass
class FrameRecord:
    game_frame: int
    level_id: int
    ovl_unit: int
    game_mode: int
    rng_seed: int
    bolts: int
    hero_state: int
    hero_substate: int
    hero_health: int
    hero_item: int
    hero_ammo: int
    hero_pos: Tuple[float, float, float]
    hero_rot: Tuple[float, float, float]
    hero_vel: Tuple[float, float, float]
    hero_anim_pos: float
    hero_mode: int
    hero_anim_cur: int
    hero_anim_next: int
    hero_anim_frame: int
    cam_type: int
    cam_pos: Tuple[float, float, float]
    cam_rot: Tuple[float, float, float]
    cam_fov: float
    ui_menu_state: int
    ui_menu_page: int
    mobys: List[MobyRecord]
    audio: List[AudioRecord]


def float_bits(v: float) -> int:
    return struct.unpack("<I", struct.pack("<f", v))[0]


def fmt_float(v: float) -> str:
    return f"{v:.6g} (0x{float_bits(v):08x})"


def floats_match(a: float, b: float, eps: float) -> bool:
    if eps <= 0.0:
        return float_bits(a) == float_bits(b)
    if math.isnan(a) or math.isnan(b):
        return math.isnan(a) and math.isnan(b)
    if math.isinf(a) or math.isinf(b):
        return a == b
    return abs(a - b) <= eps


def iter_frames(f: BinaryIO, path: str) -> Iterator[FrameRecord]:
    hdr = f.read(FILE_HDR_SIZE)
    if len(hdr) != FILE_HDR_SIZE:
        raise ValueError(f"{path}: truncated R1BT file header ({len(hdr)} bytes)")
    magic, version, _flags, _reserved = struct.unpack(FILE_HDR_FMT, hdr)
    if magic != b"R1BT":
        raise ValueError(f"{path}: bad magic {magic!r} (expected b'R1BT')")
    if version != 1:
        raise ValueError(f"{path}: unsupported R1BT version {version}")

    while True:
        raw = f.read(FRAME_HDR_SIZE)
        if not raw:
            break
        if len(raw) != FRAME_HDR_SIZE:
            raise ValueError(f"{path}: truncated frame header ({len(raw)} bytes)")
        u = struct.unpack(FRAME_HDR_FMT, raw)
        moby_count = u[35]
        audio_count = u[36]

        moby_bytes = f.read(moby_count * MOBY_SIZE)
        if len(moby_bytes) != moby_count * MOBY_SIZE:
            raise ValueError(f"{path}: truncated moby array at game_frame {u[0]}")
        mobys: List[MobyRecord] = []
        for idx in range(moby_count):
            m = struct.unpack_from(MOBY_FMT, moby_bytes, idx * MOBY_SIZE)
            mobys.append(
                MobyRecord(
                    class_id=m[0],
                    uid=m[1],
                    slot_idx=m[2],
                    mode_bits=m[3],
                    state=m[4],
                    group_id=m[5],
                    anim_cur=m[6],
                    anim_next=m[7],
                    anim_frame=m[8],
                    drawn=m[9],
                    pos=(m[11], m[12], m[13]),
                    rot=(m[14], m[15], m[16]),
                    scale=m[17],
                    anim_pos=m[18],
                )
            )

        audio_bytes = f.read(audio_count * AUDIO_SIZE)
        if len(audio_bytes) != audio_count * AUDIO_SIZE:
            raise ValueError(f"{path}: truncated audio array at game_frame {u[0]}")
        audio: List[AudioRecord] = []
        for idx in range(audio_count):
            ev = struct.unpack_from(AUDIO_FMT, audio_bytes, idx * AUDIO_SIZE)
            audio.append(AudioRecord(*ev))

        yield FrameRecord(
            game_frame=u[0],
            level_id=u[1],
            ovl_unit=u[2],
            game_mode=u[3],
            rng_seed=u[4],
            bolts=u[5],
            hero_state=u[6],
            hero_substate=u[7],
            hero_health=u[8],
            hero_item=u[9],
            hero_ammo=u[10],
            hero_pos=(u[11], u[12], u[13]),
            hero_rot=(u[14], u[15], u[16]),
            hero_vel=(u[17], u[18], u[19]),
            hero_anim_pos=u[20],
            hero_mode=u[21],
            hero_anim_cur=u[22],
            hero_anim_next=u[23],
            hero_anim_frame=u[24],
            cam_type=u[25],
            cam_pos=(u[26], u[27], u[28]),
            cam_rot=(u[29], u[30], u[31]),
            cam_fov=u[32],
            ui_menu_state=u[33],
            ui_menu_page=u[34],
            mobys=mobys,
            audio=audio,
        )


def compare_frames(a: FrameRecord, b: FrameRecord, eps: float) -> List[str]:
    diffs: List[str] = []

    def chk_int(name: str, va: int, vb: int, hex_fmt: bool = False) -> None:
        if va != vb:
            if hex_fmt:
                diffs.append(f"{name}: baseline=0x{va:08x} candidate=0x{vb:08x}")
            else:
                diffs.append(f"{name}: baseline={va} candidate={vb}")

    def chk_f(name: str, va: float, vb: float) -> None:
        if not floats_match(va, vb, eps):
            diffs.append(f"{name}: baseline={fmt_float(va)} candidate={fmt_float(vb)}")

    def chk_vec3(name: str, va: Tuple[float, float, float], vb: Tuple[float, float, float]) -> None:
        for i, axis in enumerate(("x", "y", "z")):
            chk_f(f"{name}.{axis}", va[i], vb[i])

    chk_int("game_frame", a.game_frame, b.game_frame)
    chk_int("level_id", a.level_id, b.level_id)
    chk_int("ovl_unit", a.ovl_unit, b.ovl_unit)
    chk_int("game_mode", a.game_mode, b.game_mode)
    chk_int("rng_seed", a.rng_seed, b.rng_seed, hex_fmt=True)
    chk_int("bolts", a.bolts, b.bolts)
    chk_int("hero_state", a.hero_state, b.hero_state)
    chk_int("hero_substate", a.hero_substate, b.hero_substate)
    chk_int("hero_health", a.hero_health, b.hero_health)
    chk_int("hero_item", a.hero_item, b.hero_item)
    chk_int("hero_ammo", a.hero_ammo, b.hero_ammo)
    chk_int("hero_mode", a.hero_mode, b.hero_mode)
    chk_int("hero_anim_cur", a.hero_anim_cur, b.hero_anim_cur)
    chk_int("hero_anim_next", a.hero_anim_next, b.hero_anim_next)
    chk_int("hero_anim_frame", a.hero_anim_frame, b.hero_anim_frame)
    chk_vec3("hero_pos", a.hero_pos, b.hero_pos)
    chk_vec3("hero_rot", a.hero_rot, b.hero_rot)
    chk_vec3("hero_vel", a.hero_vel, b.hero_vel)
    chk_f("hero_anim_pos", a.hero_anim_pos, b.hero_anim_pos)

    chk_int("cam_type", a.cam_type, b.cam_type)
    chk_vec3("cam_pos", a.cam_pos, b.cam_pos)
    chk_vec3("cam_rot", a.cam_rot, b.cam_rot)
    chk_f("cam_fov", a.cam_fov, b.cam_fov)

    chk_int("ui_menu_state", a.ui_menu_state, b.ui_menu_state)
    chk_int("ui_menu_page", a.ui_menu_page, b.ui_menu_page)

    if len(a.mobys) != len(b.mobys):
        diffs.append(f"moby_count: baseline={len(a.mobys)} candidate={len(b.mobys)}")
    for idx in range(min(len(a.mobys), len(b.mobys))):
        ma, mb = a.mobys[idx], b.mobys[idx]
        tag = f"moby[{idx},uid={ma.uid},cls={ma.class_id},slot={ma.slot_idx}]"
        chk_int(f"{tag}.class_id", ma.class_id, mb.class_id)
        chk_int(f"{tag}.uid", ma.uid, mb.uid)
        chk_int(f"{tag}.slot_idx", ma.slot_idx, mb.slot_idx)
        chk_int(f"{tag}.mode_bits", ma.mode_bits, mb.mode_bits, hex_fmt=True)
        chk_int(f"{tag}.state", ma.state, mb.state)
        chk_int(f"{tag}.group_id", ma.group_id, mb.group_id)
        chk_int(f"{tag}.anim_cur", ma.anim_cur, mb.anim_cur)
        chk_int(f"{tag}.anim_next", ma.anim_next, mb.anim_next)
        chk_int(f"{tag}.anim_frame", ma.anim_frame, mb.anim_frame)
        chk_int(f"{tag}.drawn", ma.drawn, mb.drawn)
        chk_vec3(f"{tag}.pos", ma.pos, mb.pos)
        chk_vec3(f"{tag}.rot", ma.rot, mb.rot)
        chk_f(f"{tag}.scale", ma.scale, mb.scale)
        chk_f(f"{tag}.anim_pos", ma.anim_pos, mb.anim_pos)
        if len(diffs) >= 24:
            break

    if len(a.audio) != len(b.audio):
        diffs.append(f"audio_count: baseline={len(a.audio)} candidate={len(b.audio)}")
    for idx in range(min(len(a.audio), len(b.audio))):
        ea, eb = a.audio[idx], b.audio[idx]
        if ea != eb:
            diffs.append(f"audio[{idx}]: baseline={ea} candidate={eb}")
            if len(diffs) >= 24:
                break

    return diffs


def compare_files(base_path: str, cand_path: str, eps: float, max_diffs: int) -> Tuple[bool, str]:
    if eps <= 0.0 and os.path.getsize(base_path) == os.path.getsize(cand_path):
        with open(base_path, "rb") as fa, open(cand_path, "rb") as fb:
            if fa.read() == fb.read():
                # Fast path: byte-for-byte identical; count frames quickly for summary.
                fa.seek(0)
                n_frames = sum(1 for _ in iter_frames(fa, base_path))
                return True, f"OK ({n_frames} frames, byte-identical)"

    diff_frames = 0
    total_frames = 0
    lines: List[str] = []
    with open(base_path, "rb") as fa, open(cand_path, "rb") as fb:
        ia = iter_frames(fa, base_path)
        ib = iter_frames(fb, cand_path)
        while True:
            ra = next(ia, None)
            rb = next(ib, None)
            if ra is None and rb is None:
                break
            if ra is None or rb is None:
                extra_a = 0 if ra is None else 1 + sum(1 for _ in ia)
                extra_b = 0 if rb is None else 1 + sum(1 for _ in ib)
                lines.append(
                    f"frame count mismatch after {total_frames} frames: "
                    f"baseline={total_frames + extra_a}, candidate={total_frames + extra_b}"
                )
                diff_frames += 1
                break
            total_frames += 1
            fdiffs = compare_frames(ra, rb, eps)
            if fdiffs:
                diff_frames += 1
                if diff_frames <= max_diffs:
                    lines.append(
                        f"  frame {ra.game_frame} (level={ra.level_id} mode={ra.game_mode}): "
                        f"{len(fdiffs)} field diff(s):"
                    )
                    for d in fdiffs[:12]:
                        lines.append(f"    - {d}")
    if diff_frames == 0:
        return True, f"OK ({total_frames} frames, eps={eps:g})"
    header = f"FAIL ({diff_frames}/{total_frames} frames differ, eps={eps:g}):\n" + "\n".join(lines)
    return False, header


def summarize_file(path: str, dump_frame: Optional[int]) -> int:
    levels = set()
    modes = set()
    total_mobys = 0
    total_audio = 0
    frames = 0
    last_hero: Optional[FrameRecord] = None
    with open(path, "rb") as f:
        for fr in iter_frames(f, path):
            frames += 1
            levels.add(fr.level_id)
            modes.add(fr.game_mode)
            total_mobys += len(fr.mobys)
            total_audio += len(fr.audio)
            last_hero = fr
            if dump_frame is not None and fr.game_frame == dump_frame:
                print(
                    f"[frame {fr.game_frame}] level={fr.level_id} ovl={fr.ovl_unit} mode={fr.game_mode} "
                    f"rng=0x{fr.rng_seed:08x} bolts={fr.bolts} hp={fr.hero_health} "
                    f"state={fr.hero_state}/{fr.hero_substate} item={fr.hero_item}(ammo={fr.hero_ammo}) "
                    f"pos=({fr.hero_pos[0]:.3f}, {fr.hero_pos[1]:.3f}, {fr.hero_pos[2]:.3f}) "
                    f"cam_type={fr.cam_type} cam_pos=({fr.cam_pos[0]:.3f}, {fr.cam_pos[1]:.3f}, {fr.cam_pos[2]:.3f}) "
                    f"mobys={len(fr.mobys)} audio={len(fr.audio)}"
                )
    print(
        f"{path}: {frames} frames, levels={sorted(levels)}, modes={sorted(modes)}, "
        f"total_moby_snaps={total_mobys}, total_audio_events={total_audio}, size={os.path.getsize(path)} B"
    )
    if last_hero is not None:
        print(
            f"  end frame {last_hero.game_frame}: level={last_hero.level_id} state={last_hero.hero_state} "
            f"pos=({last_hero.hero_pos[0]:.2f}, {last_hero.hero_pos[1]:.2f}, {last_hero.hero_pos[2]:.2f}) "
            f"rng=0x{last_hero.rng_seed:08x} bolts={last_hero.bolts} hp={last_hero.hero_health}"
        )
    return 0


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("paths", nargs="+", help="Baseline and candidate files/dirs, or single trace with --summary")
    ap.add_argument("--dir", action="store_true", help="Compare all *.r1bt files in baseline_dir vs candidate_dir")
    ap.add_argument("--summary", action="store_true", help="Print summary of a single .r1bt trace")
    ap.add_argument("--dump-frame", type=int, default=None, help="With --summary, dump a specific game_frame")
    ap.add_argument("--float-eps", type=float, default=0.0, help="Float tolerance (default 0.0 = bit-exact)")
    ap.add_argument("--max-diffs", type=int, default=5, help="Max differing frames to print per trace")
    args = ap.parse_args()

    if args.summary:
        if len(args.paths) != 1:
            ap.error("--summary expects exactly one trace path")
        return summarize_file(args.paths[0], args.dump_frame)

    if len(args.paths) != 2:
        ap.error("expected <baseline> <candidate>")

    base, cand = args.paths
    if args.dir:
        base_files = sorted(f for f in os.listdir(base) if f.endswith(".r1bt"))
        if not base_files:
            print(f"error: no .r1bt files found in {base}", file=sys.stderr)
            return 2
        ok_count = 0
        fail_count = 0
        for name in base_files:
            bp = os.path.join(base, name)
            cp = os.path.join(cand, name)
            if not os.path.exists(cp):
                print(f"[MISSING] {name}: not found in {cand}")
                fail_count += 1
                continue
            ok, msg = compare_files(bp, cp, args.float_eps, args.max_diffs)
            status = "PASS" if ok else "FAIL"
            print(f"[{status}] {name}: {msg}")
            if ok:
                ok_count += 1
            else:
                fail_count += 1
        print(f"Summary: {ok_count} passed, {fail_count} failed")
        return 0 if fail_count == 0 else 1

    ok, msg = compare_files(base, cand, args.float_eps, args.max_diffs)
    print(f"{os.path.basename(cand)}: {msg}")
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
